SELECT COALESCE(SUM(qty), 0) FROM material_receiving
WHERE material_code = #{code} AND receive_date BETWEEN #{start} AND #{end}
AND (SELECT cln.name FROM clients cln WHERE cln.client_code = material_receiving.client_code LIMIT 1) ILIKE '%' || #{clientQ} || '%'
